/**
 * `@nimbalyst/tracker-builtins` -- the built-in tracker types and the schema
 * helpers a host needs to resolve a team's overrides of them, for hosts that
 * cannot load the runtime: the collab worker.
 *
 * The builtin definitions stay where desktops load them (the runtime's
 * `builtins/*.yaml`, through `parseBuiltinTrackers`). `builtinCatalog.json` is
 * that function's output, generated by `scripts/build.mjs` and held to it by
 * the runtime's `builtinsYaml.test.ts`. The helpers are the desktop's own
 * implementations, bundled from source, so the worker resolves a delta exactly
 * as a desktop does (#1880).
 */
import type * as Api from '../types/index';
import type { FieldDefinition, TrackerDataModel, TrackerSchemaPatch as RuntimeSchemaPatch } from '@nimbalyst/tracker-schema';
import {
  diffTrackerSchema as runtimeDiffTrackerSchema,
  resolveTrackerSchemaPatch as runtimeResolveTrackerSchemaPatch,
} from '../../tracker-schema/src/schemaPatch';
import {
  decodeTrackerSchemaPayload as runtimeDecodeTrackerSchemaPayload,
  encodeTrackerSchemaPatchPayload as runtimeEncodeTrackerSchemaPatchPayload,
  TRACKER_SCHEMA_PATCH_PAYLOAD,
} from '../../runtime/src/plugins/TrackerPlugin/models/schemaSyncPayload';
import {
  addRelationshipValue as runtimeAddRelationshipValue,
  computeInverseFieldDeltas as runtimeComputeInverseFieldDeltas,
  isRelationshipField as runtimeIsRelationshipField,
  normalizeRelationshipValue as runtimeNormalizeRelationshipValue,
  removeRelationshipValue as runtimeRemoveRelationshipValue,
  serializeRelationshipValue as runtimeSerializeRelationshipValue,
} from '../../runtime/src/plugins/TrackerPlugin/models/trackerRelationships';
import catalog from './builtinCatalog.json';

const CATALOG = catalog as unknown as Api.TrackerModel[];
const BY_TYPE = new Map(CATALOG.map((model) => [model.type, model]));

function clone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

export function builtinTrackerModels(): Api.TrackerModel[] {
  return clone(CATALOG);
}

export function builtinTrackerModel(type: string): Api.TrackerModel | null {
  const model = BY_TYPE.get(type);
  return model ? clone(model) : null;
}

export function isBuiltinTrackerType(type: string): boolean {
  return BY_TYPE.has(type);
}

export function resolveTrackerSchemaPatch(seed: Api.TrackerModel, patch: Api.TrackerSchemaPatch): Api.TrackerModel {
  return runtimeResolveTrackerSchemaPatch(
    seed as unknown as TrackerDataModel,
    patch as unknown as RuntimeSchemaPatch,
  ) as unknown as Api.TrackerModel;
}

export function diffTrackerSchema(seed: Api.TrackerModel, target: Api.TrackerModel): Api.TrackerSchemaPatch {
  return runtimeDiffTrackerSchema(
    seed as unknown as TrackerDataModel,
    target as unknown as TrackerDataModel,
  ) as unknown as Api.TrackerSchemaPatch;
}

export function decodeTrackerSchemaPayload(type: string, json: string): Api.DecodedTrackerSchemaPayload | null {
  return runtimeDecodeTrackerSchemaPayload(type, json) as unknown as Api.DecodedTrackerSchemaPayload | null;
}

export function encodeTrackerSchemaPatchPayload(patch: Api.TrackerSchemaPatch): string {
  return runtimeEncodeTrackerSchemaPatchPayload(patch as unknown as RuntimeSchemaPatch);
}

export function isRelationshipField(def: { type: string }): boolean {
  return runtimeIsRelationshipField(def as Pick<FieldDefinition, 'type'>);
}

export function computeInverseFieldDeltas(
  def: Api.TrackerField,
  source: Api.InverseSourceRef,
  prev: unknown,
  next: unknown,
): Api.InverseFieldDelta[] {
  return runtimeComputeInverseFieldDeltas(def as unknown as FieldDefinition, source, prev, next) as Api.InverseFieldDelta[];
}

export function normalizeRelationshipValue(raw: unknown): Api.TrackerRelationshipValue[] {
  return runtimeNormalizeRelationshipValue(raw) as Api.TrackerRelationshipValue[];
}

export function addRelationshipValue(
  def: Api.TrackerField,
  current: unknown,
  target: Api.TrackerRelationshipValue,
): Api.TrackerRelationshipValue[] {
  return runtimeAddRelationshipValue(def as unknown as FieldDefinition, current, target) as Api.TrackerRelationshipValue[];
}

export function removeRelationshipValue(current: unknown, itemId: string): Api.TrackerRelationshipValue[] {
  return runtimeRemoveRelationshipValue(current, itemId) as Api.TrackerRelationshipValue[];
}

export function serializeRelationshipValue(
  def: Api.TrackerField,
  values: Api.TrackerRelationshipValue[],
): Api.TrackerRelationshipValue | Api.TrackerRelationshipValue[] | null {
  return runtimeSerializeRelationshipValue(def as unknown as FieldDefinition, values as never) as
    Api.TrackerRelationshipValue | Api.TrackerRelationshipValue[] | null;
}

// The published types are hand-written; fail the typecheck if they drift.
const _typesMatch: {
  TRACKER_SCHEMA_PATCH_PAYLOAD: typeof Api.TRACKER_SCHEMA_PATCH_PAYLOAD;
  builtinTrackerModels: typeof Api.builtinTrackerModels;
  builtinTrackerModel: typeof Api.builtinTrackerModel;
  isBuiltinTrackerType: typeof Api.isBuiltinTrackerType;
  resolveTrackerSchemaPatch: typeof Api.resolveTrackerSchemaPatch;
  diffTrackerSchema: typeof Api.diffTrackerSchema;
  decodeTrackerSchemaPayload: typeof Api.decodeTrackerSchemaPayload;
  encodeTrackerSchemaPatchPayload: typeof Api.encodeTrackerSchemaPatchPayload;
  isRelationshipField: typeof Api.isRelationshipField;
  computeInverseFieldDeltas: typeof Api.computeInverseFieldDeltas;
  normalizeRelationshipValue: typeof Api.normalizeRelationshipValue;
  addRelationshipValue: typeof Api.addRelationshipValue;
  removeRelationshipValue: typeof Api.removeRelationshipValue;
  serializeRelationshipValue: typeof Api.serializeRelationshipValue;
} = {
  TRACKER_SCHEMA_PATCH_PAYLOAD,
  builtinTrackerModels,
  builtinTrackerModel,
  isBuiltinTrackerType,
  resolveTrackerSchemaPatch,
  diffTrackerSchema,
  decodeTrackerSchemaPayload,
  encodeTrackerSchemaPatchPayload,
  isRelationshipField,
  computeInverseFieldDeltas,
  normalizeRelationshipValue,
  addRelationshipValue,
  removeRelationshipValue,
  serializeRelationshipValue,
};
void _typesMatch;

export { TRACKER_SCHEMA_PATCH_PAYLOAD };
export type {
  DecodedTrackerSchemaPayload,
  InverseFieldDelta,
  InverseSourceRef,
  TrackerField,
  TrackerModel,
  TrackerRelationshipValue,
  TrackerSchemaPatch,
} from '../types/index';
